targets.expr:
kube_pod_owner{namespace="$namespace", owner_kind="Job", owner_name=~"$aipubjob.*"}
* on (namespace, pod, uid, instance) group_right(owner_kind, owner_name)
kube_pod_status_phase{namespace="$namespace", pod=~"$aipubjob.*"} > 0

kube_pod_container_info{namespace="$namespace", pod="$pod"}
* on(pod, container, namespace) group_left(state) (
  label_replace(
    (kube_pod_container_status_running == 1)
    or on(pod, container, namespace) (kube_pod_container_status_waiting == 1)
    or on(pod, container, namespace) (kube_pod_container_status_terminated == 1),
    "state", "$1", "reason", "(.+)"
  )
)

sum by (exported_pod, modelName, gpu, GPU_I_PROFILE, node, GPU_I_ID) (
  gpu:resource:gpu_temp
  * on(UUID, GPU_I_ID)
  group_left(exported_pod, exported_namespace, exported_container, node)
  sgn(
    GPU_POD_UTIL_LIMIT{exported_namespace="$namespace", exported_pod=~"$aipubjob.*"}
  )
  * on (exported_namespace, exported_pod) group_left(owner_name)
  label_replace(
    label_replace(
      kube_pod_owner{
        namespace="$namespace", owner_kind="Job", owner_name=~"$aipubjob.*"
      }, "exported_namespace", "$1", "namespace", "(.+)"
    ), "exported_pod", "$1", "pod", "(.+)"
  )
)
or
sum by (exported_pod, modelName, gpu, GPU_I_PROFILE, node, GPU_I_ID) (
  gpu:resource:gpu_temp
  * on(UUID, GPU_I_ID)
  group_left(exported_pod, exported_namespace, exported_container, node)
  label_replace(
    sgn(
      MIG_POD_ALLOCATED{exported_namespace="$namespace", exported_pod=~"$aipubjob.*"}
    )
    * on (exported_namespace, exported_pod) group_left(owner_name)
    label_replace(
      label_replace(
        kube_pod_owner{
          namespace="$namespace", owner_kind="Job", owner_name=~"$aipubjob.*"
        }, "exported_namespace", "$1", "namespace", "(.+)"
      ), "exported_pod", "$1", "pod", "(.+)"
    ), "node", "$1", "Hostname", "(.+)"
  )
)

