sum by (node, gpu, UUID, GPU_I_ID, GPU_I_PROFILE, modelName, exported_namespace, exported_pod, exported_container) (
  GPU_POD_MEMORY{exported_namespace="$namespace", exported_pod=~"$aipubjob.*"}
  * on(exported_namespace, exported_pod, UUID) group_left(gpu, GPU_I_ID, GPU_I_PROFILE, exported_container)
  sgn(
    label_replace(
      MIG_POD_ALLOCATED{exported_namespace="$namespace", exported_pod=~"$aipubjob.*"}
      * on (exported_namespace, exported_pod) group_left()
      label_replace(
        label_replace(
          kube_pod_labels{namespace="$namespace", label_aipub_ten1010_io_aipubjob_name="$aipubjob"}
          , "exported_namespace", "$1", "namespace", "(.*)"
        ), "exported_pod", "$1", "pod", "(.*)"
      ), "UUID", "$1", "MIG_UUID", "(.*)"
    )
    or
    GPU_POD_UTIL_LIMIT{exported_namespace="$namespace", exported_pod!="$aipubjob.*", UUID=~"GPU.*"}
    * on (exported_namespace, exported_pod) group_left()
    label_replace(
      label_replace(
        kube_pod_labels{namespace="$namespace", label_aipub_ten1010_io_aipubjob_name="$aipubjob"}
        , "exported_namespace", "$1", "namespace", "(.*)"
      ), "exported_pod", "$1", "pod", "(.*)"
    )
  )
)

sum by (exported_pod, UUID, gpu, modelName, GPU_I_PROFILE) (
  GPU_POD_MEMORY{
    exported_namespace="$namespace",
    exported_pod=~"$job_name.*"
  }
  * on(exported_namespace, exported_pod, UUID) group_left(GPU_I_PROFILE)
  (
    sgn(
      GPU_POD_UTIL_LIMIT{
        exported_namespace="$namespace",
        exported_pod=~"$job_name.*"
      }
    )
    * on (exported_namespace, exported_pod) group_left(owner_name)
    label_replace(
      label_replace(
        kube_pod_owner{
          namespace="$namespace", owner_kind="Job", owner_name="$job_name"
        }, "exported_namespace", "$1", "namespace", "(.+)"
      ), "exported_pod", "$1", "pod", "(.+)"
    )
    unless
    label_replace(
      sgn(
        MIG_POD_ALLOCATED{
          exported_namespace="$namespace",
          exported_pod=~"$job_name.*"
        }
      )
      * on (exported_namespace, exported_pod) group_left(owner_name)
      label_replace(
        label_replace(
          kube_pod_owner{
            namespace="$namespace", owner_kind="Job", owner_name="$job_name"
          }, "exported_namespace", "$1", "namespace", "(.+)"
        ), "exported_pod", "$1", "pod", "(.+)"
      )
      ,
      "UUID", "$1", "MIG_UUID", "(.+)"
    )
    * on (exported_namespace, exported_pod, UUID) group_left()
    sgn(
      GPU_POD_UTIL_LIMIT{
        exported_namespace="$namespace",
        exported_pod=~"$job_name.*"
      }
    )
    * on (exported_namespace, exported_pod) group_left(owner_name)
    label_replace(
      label_replace(
        kube_pod_owner{
          namespace="$namespace", owner_kind="Job", owner_name="$job_name"
        }, "exported_namespace", "$1", "namespace", "(.+)"
      ), "exported_pod", "$1", "pod", "(.+)"
    )
  )
)

